const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { PatientMedicalRecord, ClinicianAssignment } = require('../models/medical');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/health.key'),
  cert: fs.readFileSync('/etc/ssl/health.crt')
});

server.on('stream', async (stream, headers) => {
  const parsed = new URL(headers[':path'], 'https://healthportal.internal');

  if (parsed.pathname === '/portal/patient-overview') {
    const patientId = parsed.searchParams.get('patientId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Unauthorized');
    }

    let clinician;
    try {
      clinician = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    // Verify clinician is actively assigned to patient before pushing medical record
    const hasAssignment = await ClinicianAssignment.isAssigned(clinician.providerId, patientId);
    if (!hasAssignment) {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: clinician not assigned to patient');
    }

    if (patientId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/records/patient/${patientId}/history.json` }, async (err, pushStream) => {
        if (err) return;
        const record = await PatientMedicalRecord.findByPatientId(patientId);
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify(record));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>Patient portal frame loaded</body></html>');
  }
});

server.listen(8444);
